from core.rules import RuleMachine


class RepairBadTopMoveRefined:
    """Mueve un tope mal puesto a una pila donde quede bien puesto.

    Variante refinada:
    - usa una fase macro ligera para fijar una fuente prioritaria;
    - ordena con más énfasis en reducir daño futuro;
    - si la fase estricta no ofrece candidatos, relaja el filtro.
    """

    name = "repair_bad_top_move"

    def __init__(
        self,
        prefer_empty=True,
        allow_relax=True,
        tighten_factor=1.0,
        source_penalty=0.5,
        dest_penalty=0.25,
    ):
        self.prefer_empty = bool(prefer_empty)
        self.allow_relax = bool(allow_relax)
        self.tighten_factor = float(tighten_factor)
        self.source_penalty = float(source_penalty)
        self.dest_penalty = float(dest_penalty)

    def start(self, partial, memory):
        stacks = partial.stacks
        h = partial.h

        def bad_top_source(i):
            if h(i) == 0 or h(i) == 1:
                return False
            grp = stacks[i][-1]
            return stacks[i][-2] < grp

        best = None
        for i in range(partial.S):
            if not bad_top_source(i):
                continue
            # Prioriza pilas con más contenedores mal puestos debajo y menor altura libre.
            score = (h(i), -partial.sorted_n[i], i)
            if best is None or score < best[0]:
                best = (score, i)

        return {"source": None if best is None else best[1]}

    def done(self, partial, memory):
        source = memory.get("source")
        if source is None:
            return True
        stacks = partial.stacks
        h = partial.h
        if h(source) == 0 or h(source) == 1:
            return True
        top = stacks[source][-1]
        return stacks[source][-2] >= top

    def allowed(self, partial, memory, candidates):
        if not candidates:
            return []

        stacks = partial.stacks
        h = partial.h
        G = partial.G
        source = memory.get("source")

        def top_group(i):
            return G if h(i) == 0 else stacks[i][-1]

        def is_bad_top_source(so):
            if h(so) <= 1:
                return False
            grp = stacks[so][-1]
            return stacks[so][-2] < grp

        def is_well_placed_at(sd, grp):
            if h(sd) == 0:
                return True
            return top_group(sd) >= grp

        strict = []
        relaxed = []

        for a in candidates:
            so = a.so
            sd = a.sd
            if so == sd:
                continue
            if h(so) == 0 or h(sd) >= partial.H:
                continue
            if source is not None and so != source:
                continue
            if not is_bad_top_source(so):
                continue

            moved = stacks[so][-1]
            if is_well_placed_at(sd, moved):
                strict.append(a)
            elif self.allow_relax:
                # relajación controlada: permite un paso temporalmente peor si
                # desbloquea una mejora fuerte en la pila fuente.
                if h(sd) == 0 or top_group(sd) >= moved - 1:
                    relaxed.append(a)

        pool = strict if strict else relaxed
        if not pool:
            # Si la fase estricta no produce nada, relaja la restricción de fuente.
            if self.allow_relax and source is not None:
                memory["source"] = None
                return self.allowed(partial, memory, candidates)
            return []

        def key(a):
            so = a.so
            sd = a.sd
            moved = stacks[so][-1]
            dest_top = top_group(sd)
            empty_score = 0 if (self.prefer_empty and h(sd) == 0) else 1

            # Preferencia por destinos que queden bien ordenados.
            tighten = abs(dest_top - moved)

            # Favorece vaciar pilas con más "daño" arriba.
            source_rank = (-partial.sorted_n[so], h(so), so)

            # Evita saturar pilas ya casi completas.
            dest_rank = (h(sd), sd)

            # Si la mejor opción fue relajada, penaliza un poco.
            relax_flag = 0 if a in strict else 1

            return (
                relax_flag,
                empty_score,
                self.tighten_factor * tighten,
                self.source_penalty * source_rank[0],
                self.dest_penalty * dest_rank[0],
                source_rank[1],
                dest_rank[1],
            )

        pool.sort(key=key)
        return pool


def build_component(problem, **params):
    return RuleMachine(
        problem,
        [
            RepairBadTopMoveRefined(
                prefer_empty=params.get("prefer_empty", True),
                allow_relax=params.get("allow_relax", True),
                tighten_factor=params.get("tighten_factor", 1.0),
                source_penalty=params.get("source_penalty", 0.5),
                dest_penalty=params.get("dest_penalty", 0.25),
            )
        ],
    )
